@spec painter_spec  src=tests/specs/painter_spec.lua  loc=292  cases=22
@exercises painter (painter)
@surface   painter.new, painter.hue, painter.wrapLines

# Intent
  painter: coordinate-parametrised, colour-disciplined drawlist binder.
  A recording ImGui stub captures DrawList_* calls so we can assert that
  positions convert through the transform, colours resolve by NAME, and the
  font path uses AddTextEx (no stack push) while measure pushes/pops.

# Helpers
  @fn rec(name)  @ 9-11
  @fn mk()  @ 53
      -- ox=100 oy=200 sx=2 sy=3 — distinct per axis so a swapped axis is caught.
  @fn widthOf(s)  @ 57
      -- Width model for the wrapLines cases: the stub's 7px-a-character metric,
      -- called directly so a case reads its budget off the character count.
  @fn last()  @ 59
  @fn has(fn)  @ 60-63

# Cases
  @case 'toScreen / fromScreen are inverse — one transform, no drift'  [pure]  @ 67-76
  @case 'fill converts both corners, resolves colour by name, passes rounding'  [pure]  @ 79-85
  @case 'stroke maps corners but leaves thickness / rounding in screen px'  [pure]  @ 88-94
  @case 'line and tri convert every endpoint'  [pure]  @ 97-107
  @case 'circle maps the centre but keeps the radius in screen px'  [pure]  @ 110-116
  @case 'polyline converts every logical pair; closed sets the closed flag'  [pure]  @ 119-128
  @case 'text without a font uses AddText at the mapped position'  [pure]  @ 131-137
  @case 'text with a font uses AddTextEx and never pushes the font stack'  [pure]  @ 140-147
  @case 'measure without a font reads CalcTextSize directly'  [pure]  @ 150-156
  @case 'measure with a font brackets CalcTextSize in Push/PopFont'  [pure]  @ 159-169
  @case 'a name routes through chrome; a token passes its packed colour straight through'  [pure]  @ 172-180
  @case 'a bare int colour is rejected — the one way to bypass the palette'  [pure]  @ 183-190
  @case 'painter.hue mints an opaque token; golden-ratio rotation makes adjacent indices distinct'  [pure]  @ 193-200
  @case 'pushClip converts both corners; intersect defaults true, explicit false respected'  [pure]  @ 203-213
  @case 'ox/oy round to whole pixels; sx/sy pass through unrounded'  [pure]  @ 216-224
  @case 'snap rounds toScreen output for fractional logical coords; fromScreen stays exact'  [pure]  @ 227-235
  @case 'wrapLines breaks on spaces and CamelCase, rejoining without a space at the case boundary'  [pure]  @ 238-243
  @case 'wrapLines balances the lines rather than filling the first — no orphan tail'  [pure]  @ 246-251
  @case 'wrapLines uses fewer lines than allowed when the text reads evenly on them'  [pure]  @ 254-258
  @case 'wrapLines packs the surplus into the last line with an ellipsis'  [pure]  @ 261-267
  @case 'wrapLines ellipsises a single atom too wide for the box; empty text is one empty line'  [pure]  @ 270-275
  @case 'path: points convert, arc keeps screen-px radius and raw angles, stroke resolves colour by name'  [pure]  @ 278-290

# Uses (outbound edges)
  @use call painter.new  @ 53,219,230
  @use call painter.hue  @ 195,196
  @use call painter.wrapLines  @ 241,242,250,256,257,263,273,274

